package ui

import "html/template"

const usersPageHTML = `<!doctype html>
<html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Пользователи | CmdUI</title><style>
:root{font-family:"IBM Plex Sans","Segoe UI",sans-serif;color:#27312d;background:#f7f8f7;font-size:14px}*{box-sizing:border-box}body{margin:0}.layout{min-height:100vh;display:grid;grid-template-columns:220px minmax(0,1fr)}aside{background:#fff;border-right:1px solid #e1e6e2;padding:22px 14px;display:flex;flex-direction:column;gap:24px}.brand{padding:0 10px;font-weight:750;color:#16845b}.nav{display:grid;gap:4px}.nav a{padding:10px;border-radius:5px;color:#4b5750;text-decoration:none}.nav a.active,.nav a:hover{background:#eaf5ef;color:#126c4a}.account{margin-top:auto;border-top:1px solid #e7ebe8;padding:15px 9px 0;color:#667169}.account strong{display:block;color:#2d3831;margin-bottom:3px}.role{font-size:12px}.logout{padding:0;border:0;background:none;color:#587064;font:inherit;text-decoration:underline;cursor:pointer;margin-top:12px}.workspace{min-width:0;padding:30px clamp(18px,4vw,54px);max-width:1300px;width:100%;margin:0 auto}.topline{border-bottom:1px solid #e1e6e2;padding-bottom:20px;margin-bottom:24px}.eyebrow{color:#78837c;font-size:12px;text-transform:uppercase}.topline h1{font-size:26px;margin:5px 0 0;font-weight:650}.notice{background:#eaf5ef;border:1px solid #cfe6d8;color:#246c4b;padding:11px 14px;margin-bottom:20px;border-radius:5px}.table-wrap{overflow-x:auto;background:#fff;border-top:1px solid #dfe5e0;border-bottom:1px solid #dfe5e0}table{width:100%;border-collapse:collapse;min-width:560px}th{text-align:left;color:#66736b;font-size:12px;padding:11px 12px;border-bottom:1px solid #e6ebe7}td{padding:12px;border-bottom:1px solid #edf0ed;vertical-align:middle}tr:last-child td{border-bottom:0}.muted{color:#78837c;font-size:12px}select{min-width:150px;height:36px;padding:0 9px;border:1px solid #cfd8d1;border-radius:4px;background:#fff;color:#27312d;font:inherit}.button{height:36px;padding:0 12px;border:1px solid #147b54;border-radius:4px;background:#147b54;color:#fff;font:inherit;font-size:12px;cursor:pointer}.button:hover{background:#0e6847}.actions{display:flex;align-items:center;gap:8px}.count{color:#78837c;font-size:12px}@media(max-width:760px){.layout{grid-template-columns:1fr}aside{border-right:0;border-bottom:1px solid #e1e6e2;padding:13px 16px;gap:9px}.nav{grid-template-columns:repeat(3,minmax(0,1fr))}.account{display:flex;align-items:center;gap:10px;border:0;padding:0;margin:0;flex-wrap:wrap}.account strong{display:inline;margin:0}.logout{margin:0 0 0 auto}.workspace{padding:22px 16px}.topline h1{font-size:23px}}
</style></head><body><div class="layout"><aside><div class="brand">CMDUI <span style="color:#77827b;font-weight:400">/ Пользователи</span></div><nav class="nav"><a href="/">Команды</a><a class="active" href="/users">Пользователи</a><a href="/runs">История запусков</a></nav><div class="account"><strong>{{.User.Username}}</strong><span class="role">Администратор</span><div style="display:block;margin-top:10px;padding-top:9px;border-top:1px solid #edf0ed;color:#66736b;font-size:11px;overflow-wrap:anywhere"><span style="display:block;color:#879188;margin-bottom:2px">Платформа</span>{{.Platform}}</div><form method="post" action="/logout"><input type="hidden" name="csrf" value="{{.CSRF}}"><button class="logout" type="submit">Выйти</button></form></div></aside><main class="workspace"><header class="topline"><div class="eyebrow">Администрирование</div><h1>Пользователи</h1></header>{{with .Notice}}<div class="notice">{{.}}</div>{{end}}<div class="table-wrap"><table><thead><tr><th>Логин</th><th>Роль</th><th>Изменить роль</th><th></th></tr></thead><tbody>{{range .Users}}<tr><td><strong>{{.Username}}</strong></td><td>{{if eq .Role "admin"}}Администратор{{else if eq .Role "operator"}}Оператор{{else}}Пользователь{{end}}</td><td><form class="actions" method="post" action="/admin/users/{{.Username}}/role"><input type="hidden" name="csrf" value="{{$.CSRF}}"><select name="role" aria-label="Новая роль для {{.Username}}"><option value="user" {{if eq .Role "user"}}selected{{end}}>Пользователь</option><option value="operator" {{if eq .Role "operator"}}selected{{end}}>Оператор</option><option value="admin" {{if eq .Role "admin"}}selected{{end}}>Администратор</option></select><button class="button" type="submit">Сохранить</button></form></td><td class="muted">{{if eq .Username $.User.Username}}Текущая учетная запись{{else if or (ne .Role "admin") (eq $.User.Username "admin")}}<form method="post" action="/admin/users/{{.Username}}/delete" data-confirm-action data-confirm-variant="danger" data-confirm-title="Удалить пользователя?" data-confirm-message="Учетная запись и ее доступ будут удалены." data-confirm-accept="Удалить"><input type="hidden" name="csrf" value="{{$.CSRF}}"><button class="button danger" type="submit">Удалить</button></form>{{else}}Только суперадминистратор может удалить админа{{end}}</td></tr>{{else}}<tr><td colspan="4" class="muted">Пользователей пока нет</td></tr>{{end}}</tbody></table></div><p class="count">{{len .Users}} учетных записей</p></main></div><dialog class="confirm-dialog" data-confirm-dialog aria-labelledby="confirm-dialog-title" aria-describedby="confirm-dialog-message"><div class="confirm-dialog-content"><h2 id="confirm-dialog-title" data-confirm-title>Подтвердите действие</h2><p id="confirm-dialog-message" data-confirm-message></p><footer class="confirm-dialog-actions"><button class="button" type="button" data-confirm-cancel>Отмена</button><button class="button primary" type="button" data-confirm-accept>Подтвердить</button></footer></div></dialog><script src="/static/confirm-actions.js" defer></script></body></html>`

var UsersTemplate = template.Must(template.New("users").Parse(withSharedStylesheet(usersPageHTML)))
